-- Zouk Atlas database schema (SQLite). Version is stored in PRAGMA user_version.
-- data/zouk_atlas.db is the source of truth; data/festivals.json and .csv are
-- exports generated by `python3 -I scripts/atlas.py export`.
PRAGMA user_version = 1;
PRAGMA foreign_keys = ON;

-- A festival series (recurring event), e.g. "Berlin Zouk Marathon".
CREATE TABLE series (
  id                    TEXT PRIMARY KEY,          -- kebab-case slug
  name                  TEXT NOT NULL,
  city                  TEXT,
  country               TEXT,
  style                 TEXT CHECK (style IN ('bz', 'bz+lambada', 'lambada', 'mixed', 'bachazouk')),
  website               TEXT,
  instagram             TEXT,
  facebook_page         TEXT,
  facebook_event_latest TEXT,
  last_checked          TEXT,                      -- YYYY-MM-DD
  position              INTEGER NOT NULL           -- keeps export order stable
);

-- Places where editions happen. Empty for now; link an edition via editions.venue_id.
CREATE TABLE venues (
  id       INTEGER PRIMARY KEY,
  name     TEXT NOT NULL,
  address  TEXT,
  city     TEXT,
  country  TEXT,
  lat      REAL,
  lon      REAL,
  website  TEXT,
  notes    TEXT
);

-- One year's edition of a series.
CREATE TABLE editions (
  series_id              TEXT NOT NULL REFERENCES series(id) ON DELETE CASCADE,
  year                   INTEGER NOT NULL,
  start_date             TEXT,                     -- YYYY-MM-DD
  end_date               TEXT,
  source                 TEXT,                     -- where the dates come from
  confirmed_by_organizer INTEGER CHECK (confirmed_by_organizer IN (0, 1)),  -- NULL = not stated
  city                   TEXT,                     -- only when this edition is elsewhere than series.city
  country                TEXT,
  venue_id               INTEGER REFERENCES venues(id),
  PRIMARY KEY (series_id, year)
);

-- Research status of a series for a given year (e.g. 2027: 'listed', 'expected').
CREATE TABLE year_status (
  series_id TEXT NOT NULL REFERENCES series(id) ON DELETE CASCADE,
  year      INTEGER NOT NULL,
  status    TEXT NOT NULL,
  note      TEXT,
  PRIMARY KEY (series_id, year)
);

-- Hotels. Empty for now; link to editions through edition_hotels.
CREATE TABLE hotels (
  id       INTEGER PRIMARY KEY,
  name     TEXT NOT NULL,
  address  TEXT,
  city     TEXT,
  country  TEXT,
  lat      REAL,
  lon      REAL,
  website  TEXT,
  notes    TEXT
);

CREATE TABLE edition_hotels (
  series_id      TEXT NOT NULL,
  year           INTEGER NOT NULL,
  hotel_id       INTEGER NOT NULL REFERENCES hotels(id) ON DELETE CASCADE,
  role           TEXT CHECK (role IN ('official', 'partner', 'nearby')),
  price_from_eur REAL,
  notes          TEXT,
  PRIMARY KEY (series_id, year, hotel_id),
  FOREIGN KEY (series_id, year) REFERENCES editions(series_id, year) ON DELETE CASCADE
);

CREATE INDEX editions_by_date ON editions(start_date);
CREATE INDEX year_status_by_status ON year_status(year, status);
